/* Local MIDI timbre profile setting. The profiles are generated by code; no sample bank is loaded. */
(() => {
  "use strict";
  const core = window.Trk && window.Trk.core;
  const api = window.Trk && window.Trk.midiProfiles;
  const select = document.getElementById("midiSoundProfile");
  if (!core || !api || !select) return;

  function profileName(profile) {
    const language = core.settings.language || "en";
    return profile.name && (profile.name[language] || profile.name.en || profile.name.ja) || profile.id;
  }
  function render() {
    const profiles = api.list();
    const selected = api.normalize(core.settings.midiSoundProfile);
    if (core.settings.midiSoundProfile !== selected) {
      core.settings.midiSoundProfile = selected;
      core.saveUserPrefs();
    }
    select.textContent = "";
    for (const [category, groupKey] of [["reference", "midiProfileReference"], ["trk", "midiProfileOriginal"]]) {
      const items = profiles.filter(profile => profile.category === category);
      if (!items.length) continue;
      const group = document.createElement("optgroup");
      group.label = tr(groupKey);
      for (const profile of items) {
        const option = document.createElement("option");
        option.value = profile.id;
        option.textContent = profileName(profile);
        group.append(option);
      }
      select.append(group);
    }
    select.value = selected;
  }

  select.addEventListener("change", () => {
    core.settings.midiSoundProfile = api.normalize(select.value);
    select.value = core.settings.midiSoundProfile;
    core.saveUserPrefs();
  });
  if (typeof core.on === "function") {
    core.on("language", render);
    core.on("audioPrefsReset", render);
  }
  render();
})();
